\label{ass: crucial}
    We have that $\nu <1 $, where 
    $$\nu =L\max_{h\in \{1,\cdots,q\}} \alpha_h \left\| \left(p_{h \to \ell}\mathcal S \left(\left|\phi^{h \to \ell}\right |\right)\right)_{(\ell,h)\in \{1,\cdots,q\}^2}\right\|_2.$$

\label{ass:crucial_strong}
    We have that $\nu_{\mathcal S}<1$, where 
    $$\nu_{\mathcal S} =L\max_{h\in \{1,\cdots,q\}} \alpha_h \mathcal S \left(\left\| \left(p_{h \to \ell}\left|\phi^{h \to \ell}\right |\right)_{(\ell,h)\in \{1,\cdots,q\}^2}\right\|_2\right).$$

\label{ass:uniform}
    We have that $\nu'<1$ where
    $$\nu' = L\left \|\left(\alpha_h p^{h \to \ell}\mathcal S \left(\left | \phi^{h \to \ell}\right |\right)\right)_{(\ell,h)\in \{1,\cdots,q\}} \right \|_\infty.$$

\label{ass:uniform_strong}
    We have that $\nu'_{\mathcal S}<1$ where
    $$\nu'_{\mathcal S} = L \mathcal S \left(\left \|\left(\alpha_h p^{h \to \ell}\left | \phi^{h \to \ell}\right |\right)_{(\ell,h)\in \{1,\cdots,q\}} \right \|_\infty\right).$$

To keep this work at a reasonable length, we only give a partial proof of this theorem. For $i \in \{1,\cdots,N\}$, we have that 
    \begin{align*}
        {\mathbb E} \left [\int _0^T \left | \mathrm d H^{i,N}_t-\mathrm d \bar H^{i,N}_t  \right |\right]=&{\mathbb E} \left [\int _0^T \left | \int_{{\mathbb R}_+}(\mathds 1_{\theta \le \lambda^{i,N}_t}-\mathds 1_{\theta \le \bar\lambda^{i,N}_t}) \Gamma^i(\mathrm d t,\mathrm d \theta )  \right |\right]\\
        \le&{\mathbb E} \left [\int _0^T  \int_{{\mathbb R}_+}\left |\mathds 1_{\theta \le \lambda^{i,N}_t}-\mathds 1_{\theta \le \bar\lambda^{i,N}_t}\right |\Gamma^i(\mathrm d t,\mathrm d \theta )  \right]\\
        =& {\mathbb E} \left[\int_0^T \left|\lambda ^{i,N}_t-\bar \lambda^{i,N}_t \right | \mathrm d t\right].
    \end{align*}
    Therefore, using the Cauchy-Schwarz inequality we have that 
    \begin{align*}
        \frac{1}{N} \sum_{i=1}^N\frac{1}{T}{\mathbb E} \left [\int _0^T \left | \mathrm d H^{i,N}_t-\mathrm d \bar H^{i,N}_t  \right |\right] \le &\frac{1}{N} \sum_{i=1}^N\frac{1}{T}{\mathbb E} \left[\int_0^T \left|\lambda ^{i,N}_t-\bar \lambda^{i,N}_t \right | \mathrm d t\right]\\
        \leq & \frac{1}{\sqrt N} \sqrt{\sum_{i=1}^N \left(\frac{1}{T}{\mathbb E} \left[\int_0^T \left| \lambda^{i,N}_t-\bar \lambda^{i,N}_t\right| \mathrm d t\right]\right)^2}\\
        =&\frac{1}{\sqrt N} \sqrt{\left \|\frac{1}{T}{\mathbb E} \left[\int_0^T \left| \lambda^{N}_t-\bar \lambda^{N}_t\right| \mathrm d t\right] \right \|_2}.
    \end{align*}
    We then proceed to bound the difference between the intensities from above alongside Proposition \ref{prop:lambda_hat} and Proposition \ref{prop:hat_bar}.

\label{lmm:convolution}
    Let $(A_k)_{k\in {\mathbb N}}$ be a family of non-negative matrices satisfying $A_0=0$ and $\rho \left (\mathcal S(A)\right)<1$. If a vector sequence $(x_t)_{t\in {\mathbb N}}$ satisfies 
    \begin{equation}
    \label{ineq:conv}
        |x_{t}|\preceq \sum_{k=0}^{t}A_{t-k} |x_{k}| + W_t,
    \end{equation}  
    for any $t\in {\mathbb N}$ and for some vector $(W_t)_{t \in {\mathbb N}}$, the
    $$|x_t| \preceq \left (\left(\sum_{m=0}^{+\infty}  A ^{(*m)} \right)*W\right)_t.$$
    In particular, if there exists a nonnegative constant vector sequence $\bar{W}$ such as $W_t \preceq \bar W$ then
    $$|x_t|_{ }\preceq \left (I-\sum_{k\geq 1}A_k \right)^{-1}\bar W.$$
